#pragma once
#include "resource_commands131.hpp"
namespace wht {
inline bool IsResourceTransfer131(const std::wstring& name){return name==L"#gg"||name==L"#gl"||name==L"#ggl"||name==L"#gll";}
struct ResourceTransferRequest131 {unsigned slot=24;int amounts[2]{};};
inline bool ParseResourceTransfer131(const std::wstring& name,const std::wstring& args,ResourceTransferRequest131& out){if(!IsResourceTransfer131(name)||args.find(L'\0')!=std::wstring::npos||args.find_first_of(L"\r\n")!=std::wstring::npos)return false;std::wistringstream in(args);in.imbue(std::locale::classic());long long slot=0,a=0,b=0;std::wstring extra;const bool single=name==L"#gg"||name==L"#gl";if(!(in>>slot>>a)||(!single&&!(in>>b))||in>>extra||slot<1||slot>24||a<0||a>INT_MAX||b<0||b>INT_MAX||(!a&&!b))return false;ResourceTransferRequest131 v;v.slot=unsigned(slot-1);const bool wood=name==L"#gl"||name==L"#gll";v.amounts[0]=int(wood?b:a);v.amounts[1]=int(wood?a:b);out=v;return true;}
struct ResourceTransferSource131 {ResourceCommandSource131 source,target;};
inline bool SameResourceTransfer131(const ResourceTransferSource131& a,const ResourceTransferSource131& b){return SameResourcePlayer131(a.source,b.source)&&SameResourcePlayer131(a.target,b.target)&&a.source.world==a.target.world&&a.source.local==a.target.local&&a.source.player!=a.target.player&&a.source.physical!=a.target.physical;}
inline bool ReadResourceTransfer131(uintptr_t base,unsigned build,unsigned slot,ResourceTransferSource131& out){if(slot>=24)return false;ResourceTransferSource131 v;if(!ReadResourceCommand131(base,build,v.source)||slot==v.source.local)return false;const auto* p=ResourceProfileFor131(build);if(!p)return false;
 __try{const auto getPlayer=reinterpret_cast<uintptr_t(__thiscall*)(uintptr_t,unsigned)>(base+p->playerFn);const auto get=reinterpret_cast<int(__thiscall*)(uintptr_t)>(base+p->integerFn);v.target.world=v.source.world;v.target.local=v.source.local;v.target.player=getPlayer(v.source.world,slot);if(!ResourceIdentity131(v.target.player,base,p->playerTable)||*reinterpret_cast<int*>(v.target.player+p->statusOffset)!=1)return false;v.target.physical=*reinterpret_cast<unsigned char*>(v.target.player+p->idOffset);if(v.target.physical>=24||v.target.physical==v.source.physical||v.target.player==v.source.player)return false;
 for(unsigned i=0;i<2;++i){const int raw=get(v.target.player+p->stateBase+(i+1)*p->stateStride);if(raw<0)return false;v.target.values[i]=raw/10;}
 ResourceCommandSource131 check;if(!ReadResourceCommand131(base,build,check)||!SameResourcePlayer131(v.source,check)||getPlayer(v.source.world,slot)!=v.target.player||!ResourceIdentity131(v.target.player,base,p->playerTable)||*reinterpret_cast<unsigned char*>(v.target.player+p->idOffset)!=v.target.physical||*reinterpret_cast<int*>(v.target.player+p->statusOffset)!=1)return false;v.source=check;out=v;return true;
 }__except(1){return false;}}
inline bool InvokeResourceTransferSet131(ResourceSetNative131 set,uintptr_t player,unsigned state,int value){if(!set||!player||(state!=1&&state!=2)||value<0||value>9999999)return false;__try{set(player,state,value);return true;}__except(1){return false;}}
inline bool SetResourceTransferNative131(uintptr_t base,unsigned build,unsigned slot,const ResourceTransferSource131& source,bool recipient,unsigned state,int value){if(state<1||state>2)return false;ResourceTransferSource131 current;if(!ReadResourceTransfer131(base,build,slot,current)||!SameResourceTransfer131(source,current))return false;for(unsigned i=0;i<2;++i)if(source.source.values[i]!=current.source.values[i]||source.target.values[i]!=current.target.values[i])return false;const auto* p=ResourceCommandProfileFor131(build);return p&&InvokeResourceTransferSet131(reinterpret_cast<ResourceSetNative131>(base+p->set),recipient?current.target.player:current.source.player,state,value);}
inline bool ResourceTransferBalances131(const ResourceTransferSource131& a,const ResourceTransferSource131& b){if(!SameResourceTransfer131(a,b))return false;for(unsigned i=0;i<2;++i)if(a.source.values[i]!=b.source.values[i]||a.target.values[i]!=b.target.values[i])return false;return true;}
template<class Read,class Set> bool ResourceTransferFlow131(const ResourceTransferRequest131& request,Read read,Set set,std::string& report){if(request.slot>=24||request.amounts[0]<0||request.amounts[1]<0||(!request.amounts[0]&&!request.amounts[1])){report="Transfer: invalid request";return false;}ResourceTransferSource131 before,current;if(!read(request.slot,before)||!read(request.slot,current)||!ResourceTransferBalances131(before,current)){report="Transfer: stable active source and recipient required (not self)";return false;}int from[2]{},to[2]{};for(unsigned i=0;i<2;++i){const int amount=request.amounts[i];if(current.source.values[i]<amount||current.source.values[i]>9999999||current.target.values[i]<0||static_cast<int64_t>(current.target.values[i])+amount>9999999){report="Transfer: insufficient balance or native resource limit";return false;}from[i]=current.source.values[i]-amount;to[i]=current.target.values[i]+amount;}
 unsigned attempted=0;auto failure=[&](){report=attempted?"Transfer interrupted: some debits or credits may have applied; check balances":"Transfer rejected: player or balances changed";return false;};
 for(unsigned i=0;i<2;++i){if(!request.amounts[i])continue;for(unsigned side=0;side<2;++side){ResourceTransferSource131 check,after;if(!read(request.slot,check)||!ResourceTransferBalances131(current,check))return failure();++attempted;if(!set(request.slot,check,side!=0,i+1,side?to[i]:from[i]))return failure();auto expected=check;(side?expected.target:expected.source).values[i]=side?to[i]:from[i];if(!read(request.slot,after)||!ResourceTransferBalances131(expected,after))return failure();current=after;}}
 report="Transferred Gold "+std::to_string(request.amounts[0])+", Lumber "+std::to_string(request.amounts[1])+" to Player "+std::to_string(request.slot+1);return true;}
template<class Read,class Set> bool ResourceTransferCommand131(const std::wstring& name,const std::wstring& args,Read read,Set set,std::string& report){ResourceTransferRequest131 request;if(!ParseResourceTransfer131(name,args,request)){report="Usage: #gg/#gl player(1..24) amount; #ggl player(1..24) gold lumber; #gll player(1..24) lumber gold";return false;}return ResourceTransferFlow131(request,read,set,report);}
}
